int main() {
    int N, M, C;
    if (scanf("%d %d %d", &N, &M, &C) != 3) return 0;

    int next[100005] = {0};
    int visited[100005] = {0};

    for (int i = 0; i < N; i++) {
        int A, D;
        scanf("%d %d", &A, &D);
        if (next[D] == 0) {
            next[D] = A;
        }
    }

    int cur = C;
    int swaps = 0;

    while (1) {
        if (next[cur] == 0) {
            printf("%d\n", swaps);
            return 0;
        }

        if (visited[cur]) {
            printf("-1\n");
            return 0;
        }

        visited[cur] = 1;
        cur = next[cur];
        swaps++;
    }

    return 0;
}
